/*
 * High-performance portfolio calculations using C extension
 *
 * Implements the same arithmetic as the pure-Python baseline but in C,
 * using the NumPy C API for zero-copy access to contiguous float64 arrays.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/*
 * Convert an arbitrary sequence/array to a C-contiguous, aligned float64
 * NumPy array.  For inputs that already have the right layout this is a
 * zero-copy incref, so the hot path does not pay for a copy.
 */
static PyArrayObject *as_double_array(PyObject *obj) {
    return (PyArrayObject *)PyArray_FROM_OTF(obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    PyArrayObject *weights_array = as_double_array(weights_obj);
    if (!weights_array)
        return NULL;

    PyArrayObject *cov_array = as_double_array(cov_obj);
    if (!cov_array) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights must be a 1-D array");
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return NULL;
    }
    if (PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must be a 2-D array");
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return NULL;
    }

    const npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must be a square matrix matching weights");
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return NULL;
    }

    const double *w = (const double *)PyArray_DATA(weights_array);
    const double *cov = (const double *)PyArray_DATA(cov_array);

    /* risk_squared = x^T * S * x, accumulated in the same order as the
     * Python baseline: temp = S*x, then x . temp. */
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        const double *row = cov + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j)
            row_sum += row[j] * w[j];
        risk_squared += w[i] * row_sum;
    }

    Py_DECREF(weights_array);
    Py_DECREF(cov_array);

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    PyArrayObject *weights_array = as_double_array(weights_obj);
    if (!weights_array)
        return NULL;

    PyArrayObject *returns_array = as_double_array(returns_obj);
    if (!returns_array) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1 ||
        PyArray_NDIM(returns_array) != 1 ||
        PyArray_DIM(weights_array, 0) != PyArray_DIM(returns_array, 0)) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must be 1-D arrays of equal length");
        Py_DECREF(weights_array);
        Py_DECREF(returns_array);
        return NULL;
    }

    const npy_intp n = PyArray_DIM(weights_array, 0);
    const double *w = (const double *)PyArray_DATA(weights_array);
    const double *r = (const double *)PyArray_DATA(returns_array);

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        total_return += w[i] * r[i];

    Py_DECREF(weights_array);
    Py_DECREF(returns_array);

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}

/*
 * High-performance portfolio calculations using C extension
 *
 * Uses the NumPy C API for zero-copy access to contiguous float64 arrays,
 * and also accepts plain Python sequences (e.g. the list-of-lists covariance
 * matrix produced by the baseline).  For nested Python sequences the rows are
 * unpacked straight into a C scratch buffer, avoiding the costly creation of
 * a full NumPy array from millions of Python floats.
 *
 * The arithmetic and its evaluation order match the pure-Python baseline
 * exactly, so results agree to well within the 1e-10 tolerance.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

/* Convert an arbitrary object to a C-contiguous, aligned float64 array.
 * Zero-copy (just an incref) when the input already has that layout. */
static PyArrayObject *as_double_array(PyObject *obj) {
    return (PyArrayObject *)PyArray_FROM_OTF(obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
}

/* Extract one Python number as a C double.  Returns 0 on success, -1 on
 * error (with a Python exception set). */
static inline int item_to_double(PyObject *o, double *out) {
    if (PyFloat_CheckExact(o)) {
        *out = PyFloat_AS_DOUBLE(o);
        return 0;
    }
    double v = PyFloat_AsDouble(o);
    if (v == -1.0 && PyErr_Occurred())
        return -1;
    *out = v;
    return 0;
}

/* Fill buf[0..n) from a Python sequence of exactly n numbers. */
static int fill_from_sequence(PyObject *seq, double *buf, npy_intp n) {
    PyObject *fast = PySequence_Fast(seq, "expected a sequence of numbers");
    if (!fast)
        return -1;
    if (PySequence_Fast_GET_SIZE(fast) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "sequence length does not match the expected size");
        Py_DECREF(fast);
        return -1;
    }
    PyObject **items = PySequence_Fast_ITEMS(fast);
    for (npy_intp j = 0; j < n; ++j) {
        if (item_to_double(items[j], &buf[j]) < 0) {
            Py_DECREF(fast);
            return -1;
        }
    }
    Py_DECREF(fast);
    return 0;
}

/* Fill buf[0..n) from either a 1-D float64 NumPy array or a Python sequence. */
static int get_vector(PyObject *obj, double *buf, npy_intp n) {
    if (PyArray_Check(obj)) {
        PyArrayObject *a = as_double_array(obj);
        if (!a)
            return -1;
        if (PyArray_NDIM(a) != 1 || PyArray_DIM(a, 0) != n) {
            PyErr_SetString(PyExc_ValueError,
                            "weights must be a 1-D array matching the matrix size");
            Py_DECREF(a);
            return -1;
        }
        memcpy(buf, PyArray_DATA(a), (size_t)n * sizeof(double));
        Py_DECREF(a);
        return 0;
    }
    return fill_from_sequence(obj, buf, n);
}

static inline double dot_product(const double *a, const double *b, npy_intp n) {
    double sum = 0.0;
    for (npy_intp j = 0; j < n; ++j)
        sum += a[j] * b[j];
    return sum;
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    /* ---- Determine the portfolio size and get the weights vector ---- */
    PyArrayObject *cov_array = NULL;
    PyObject *rows_fast = NULL;
    npy_intp n;

    if (PyArray_Check(cov_obj)) {
        cov_array = as_double_array(cov_obj);
        if (!cov_array)
            return NULL;
        if (PyArray_NDIM(cov_array) != 2 ||
            PyArray_DIM(cov_array, 0) != PyArray_DIM(cov_array, 1)) {
            PyErr_SetString(PyExc_ValueError, "cov_matrix must be a square 2-D array");
            Py_DECREF(cov_array);
            return NULL;
        }
        n = PyArray_DIM(cov_array, 0);
    } else {
        n = PySequence_Size(cov_obj);
        if (n < 0) {
            PyErr_SetString(PyExc_TypeError,
                            "cov_matrix must be a 2-D array or a sequence of rows");
            return NULL;
        }
        rows_fast = PySequence_Fast(cov_obj, "cov_matrix must be a sequence of rows");
        if (!rows_fast)
            return NULL;
    }

    double *weights = NULL;
    double *scratch = NULL;
    PyObject *result = NULL;

    weights = (double *)malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
    scratch = (double *)malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
    if (!weights || !scratch) {
        PyErr_NoMemory();
        goto done;
    }

    if (get_vector(weights_obj, weights, n) < 0)
        goto done;

    /* ---- risk_squared = x^T * S * x, in the baseline's order ---- */
    double risk_squared = 0.0;

    if (cov_array) {
        /* Fast path: fully contiguous float64 matrix, read rows directly. */
        const double *cov = (const double *)PyArray_DATA(cov_array);
        for (npy_intp i = 0; i < n; ++i) {
            double row_sum = dot_product(cov + i * n, weights, n);
            risk_squared += weights[i] * row_sum;
        }
    } else {
        PyObject **rows = PySequence_Fast_ITEMS(rows_fast);
        for (npy_intp i = 0; i < n; ++i) {
            PyObject *row = rows[i];
            const double *row_data;

            if (PyArray_Check(row)) {
                /* Row is itself a NumPy array: use it zero-copy. */
                PyArrayObject *row_array = as_double_array(row);
                if (!row_array)
                    goto done;
                if (PyArray_NDIM(row_array) != 1 || PyArray_DIM(row_array, 0) != n) {
                    PyErr_SetString(PyExc_ValueError,
                                    "each cov_matrix row must have one entry per asset");
                    Py_DECREF(row_array);
                    goto done;
                }
                row_data = (const double *)PyArray_DATA(row_array);
                double row_sum = dot_product(row_data, weights, n);
                risk_squared += weights[i] * row_sum;
                Py_DECREF(row_array);
            } else {
                if (fill_from_sequence(row, scratch, n) < 0)
                    goto done;
                double row_sum = dot_product(scratch, weights, n);
                risk_squared += weights[i] * row_sum;
            }
        }
    }

    result = PyFloat_FromDouble(sqrt(risk_squared));

done:
    free(weights);
    free(scratch);
    Py_XDECREF(cov_array);
    Py_XDECREF(rows_fast);
    return result;
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    npy_intp n = PySequence_Size(weights_obj);
    if (n < 0) {
        PyErr_Clear();
        if (PyArray_Check(weights_obj) && PyArray_NDIM((PyArrayObject *)weights_obj) == 1)
            n = PyArray_DIM((PyArrayObject *)weights_obj, 0);
        else {
            PyErr_SetString(PyExc_TypeError, "weights must be a 1-D array or sequence");
            return NULL;
        }
    }

    double *weights = (double *)malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
    double *returns = (double *)malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
    PyObject *result = NULL;

    if (!weights || !returns) {
        PyErr_NoMemory();
        goto done;
    }
    if (get_vector(weights_obj, weights, n) < 0)
        goto done;
    if (get_vector(returns_obj, returns, n) < 0)
        goto done;

    result = PyFloat_FromDouble(dot_product(weights, returns, n));

done:
    free(weights);
    free(returns);
    return result;
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}

